import numpy as np


def q311(query, keys, values, w_query, w_key, scoring_vector):
    scores = (
        np.tanh(np.asarray(query) @ w_query + np.asarray(keys) @ w_key)
        @ scoring_vector
    )
    weights = np.exp(scores - scores.max())
    weights /= weights.sum()
    return (weights @ values, weights)
